={{
  {
    statement: "MATCH (m:Movie) WHERE m.title = $movie_title OPTIONAL MATCH (m)-[:SIMILAR_THEME_TO]-(related:Movie) WITH m, collect(DISTINCT {title: related.title, year: related.year}) AS similarMovies OPTIONAL MATCH (m)-[:HAS_GENRE]-(g:Genre)-[:HAS_GENRE]-(genreMovie:Movie) WHERE genreMovie <> m RETURN m.title AS searchedMovie, similarMovies, collect(DISTINCT {title: genreMovie.title, year: genreMovie.year, genre: g.name}) AS moviesWithSharedGenres",
    parameters: {
      movie_title: $json.movie_title
    }
  }
}}

parameters.jsCode:
const result = $input.first().json.data;

const fields = result.fields;
const values = result.values;

if (!values || values.length === 0) {
  return [{
    json: {
      graphResults: "Ingen filmrelationer blev fundet."
    }
  }];
}

const row = Object.fromEntries(
  fields.map((field, index) => [field, values[0][index]])
);

const similarMovies = row.similarMovies || [];
const sharedGenres = row.moviesWithSharedGenres || [];

const similarText = similarMovies
  .map(movie => `${movie.title} (${movie.year})`)
  .join(", ");

const genreText = sharedGenres
  .map(movie => `${movie.title} (${movie.year}) – ${movie.genre}`)
  .join("\n");

const graphResults = `
Søgt film: ${row.searchedMovie}

Film med lignende temaer:
${similarText || "Ingen fundet"}

Film med fælles genrer:
${genreText || "Ingen fundet"}
`;

return [{
  json: {
    graphResults
  }
}];
